'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,state;try{state=JSON.parse(localStorage.getItem('catalyst-v1')||'null')}catch{storageOK=false}state={attempts:[],completed:[],tasks:{},results:[],plan:null,focus:0,...state};
function save(){try{localStorage.setItem('catalyst-v1',JSON.stringify(state))}catch{storageOK=false;toast('Browser storage unavailable. Progress will last for this session.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const subjects=[{id:'qa',name:'Quantitative Aptitude',short:'QA',icon:'∑',color:'purple',desc:'Build your number sense, one concept at a time.'},{id:'varc',name:'Verbal Ability & Reading',short:'VARC',icon:'Aa',color:'green',desc:'Read between the lines. Find your perspective.'},{id:'dilr',name:'Data Interpretation & Logic',short:'DILR',icon:'▥',color:'orange',desc:'Turn a little information into a clear insight.'}];
// All teaching material and questions below are original practice content.
const lessons=[
['percentages','qa','Percentages & successive change','The foundation of arithmetic.', 'A percentage is a fraction with denominator 100. Always identify the base before calculating a change.','Percentage change = (new − original) ÷ original × 100. Successive changes a% and b% combine to a + b + ab/100 percent (use a negative sign for decreases).','A price rises 20% and falls 20%. On a base of 100 it becomes 120, then 96: a net loss of 4%.','A 25% increase is reversed by a 20% decrease, because the second base is larger.'],
['ratio','qa','Ratios, proportions & mixtures','Compare quantities and combine groups.', 'A ratio compares like quantities. Scale both sides by the same factor, and use a shared variable to connect ratios. Weighted averages depend on group sizes.','If A:B = m:n, write A = mk and B = nk. Weighted mean = Σ(weight × value) / Σweights.','Mix 2 litres at ₹30/L with 3 litres at ₹50/L. Average cost = (2×30 + 3×50)/5 = ₹42/L.','Do not average two averages unless the group sizes are equal.'],
['profit','qa','Profit, loss & interest','Follow the money and the correct base.', 'Profit and loss percentages use cost price as the base. Discounts use marked price. Compound interest applies interest to the updated principal each period.','Profit% = (SP − CP)/CP × 100. Amount = P(1 + r/100)^n for annual compounding.','Cost ₹800, marked ₹1,200, discount 20%: selling price ₹960, profit ₹160 = 20%.','A discount percentage and a profit percentage generally use different bases.'],
['work','qa','Time, work & pipes','Think in rates, rather than days.', 'If a person finishes a job in x days, their daily rate is 1/x. Add rates for collaboration; subtract rates for a drain or opposing action.','Combined time = 1 / (1/a + 1/b) = ab/(a+b), for two independent constant-rate workers.','A takes 12 days, B takes 18. Combined rate = 5/36; time = 36/5 = 7.2 days.','Rates can be added directly. Completion times cannot.'],
['speed','qa','Time, speed & distance','Make motion problems stand still.', 'Use a consistent unit system. Relative speed is the sum for opposite motion and the difference for same-direction motion. Average speed is total distance divided by total time.','Distance = speed × time. For equal distances at speeds a and b: average speed = 2ab/(a+b).','Travel 60 km at 30 km/h and return at 60 km/h. Total 120 km in 3 hours: average 40 km/h.','The arithmetic average of speeds only works for equal travel times.'],
['algebra','qa','Equations & inequalities','Translate a story into a solvable relationship.', 'Define variables clearly. Preserve equivalence when solving equations. Multiplying an inequality by a negative number reverses its direction.','(a+b)² = a² + 2ab + b². Roots of ax²+bx+c = 0 have sum −b/a and product c/a.','If x + 1/x = 3, squaring gives x² + 2 + 1/x² = 9. Thus x² + 1/x² = 7.','Squaring can introduce extra roots. Substitute candidate answers back into the original equation.'],
['numbers','qa','Number systems','Divisibility, factors and remainders.', 'Prime factorization is the building block for divisors, HCF and LCM. A remainder r on division by d satisfies 0 ≤ r < d.','If n = p^a q^b, number of positive divisors = (a+1)(b+1). For two positive integers: HCF × LCM = product.','72 = 2³ × 3², so it has (3+1)(2+1) = 12 positive divisors.','1 is neither prime nor composite. Check whether a question asks for positive or all integer factors.'],
['geometry','qa','Geometry & mensuration','Draw first. Calculate second.', 'Mark known angles, lengths and parallel lines on a clear diagram. Similar triangles have proportional corresponding sides; areas scale as the square of the length ratio.','Triangle area = ½bh. Circle area = πr². Pythagoras: a²+b²=c². Sum of polygon interior angles = (n−2)180°.','A right triangle with legs 6 and 8 has hypotenuse 10 and area 24 square units.','Do not assume a diagram is to scale or infer equal lengths without evidence.'],
['modern','qa','Counting, probability & sets','Count systematically, with no overlaps.', 'Decide whether order matters. Use permutations for ordered selections and combinations for unordered selections. A probability counts favourable outcomes over equally likely outcomes.','nCr = n!/[r!(n−r)!]. P(A or B) = P(A)+P(B)−P(A and B). |A∪B| = |A|+|B|−|A∩B|.','Choose 2 people from 5: 5C2 = 10. Choosing a president and secretary instead gives 5×4 = 20.','A combination counts groups; a permutation counts arrangements.'],
['rc','varc','Reading comprehension','Find the argument behind the words.', 'Map each paragraph to its role: introduce, contrast, illustrate, qualify or conclude. Identify what the author believes and how evidence supports that belief.','Read → map → predict → eliminate. Separate what the passage states from what you already know.','If a passage says “technology can improve access, provided training is available,” the claim is conditional. “Technology always improves access” is too strong.','Extreme options, reversed relationships and statements outside the passage are common traps.'],
['inference','varc','Inference & critical reasoning','Make the smallest defensible leap.', 'An inference must follow from the given information. An assumption is an unstated premise required by an argument. Evidence that breaks that premise weakens the conclusion.','For assumptions, negate the option: if the argument collapses, it may be necessary. For inference, demand textual support.','“The library extended its hours, so attendance will rise” assumes some potential users were constrained by the previous hours.','Plausible is not the same as supported. Never add outside facts to repair an argument.'],
['summary','varc','Paragraph summaries','Keep the central claim and its qualification.', 'First express the paragraph in your own short sentence. A good summary preserves its scope, main relationship and tone while dropping examples.','Topic + central claim + essential qualifier. Reject options that introduce new causes or remove a condition.','“Remote work cuts commuting, but benefits depend on home conditions” becomes: remote work offers commuting benefits whose impact varies with home conditions.','An option may repeat many passage words and still distort the argument.'],
['parajumbles','varc','Paragraph ordering & odd sentence','Follow the thread of an argument.', 'Look for an opening idea, mandatory pairs and a conclusion. Pronouns usually follow the nouns they refer to. Examples typically follow a general claim.','Find anchors → connect pairs → test the full sequence. For odd sentence questions, check both topic and logical role.','“A new reservoir was built.” precedes “It now supplies nearby villages,” because “it” needs a referent.','A sentence can share vocabulary with the others but interrupt their reasoning.'],
['reading','varc','Reading habits & passage strategy','Develop comprehension without rushing.', 'Read across science, history, philosophy, economics and social questions. After a passage, recall its argument without looking back. Track comprehension before increasing pace.','Daily practice: 20 minutes reading + 5 minutes argument mapping + a short written summary.','Write one sentence per paragraph, then a single sentence for the whole passage. Compare the map with the author’s final conclusion.','Reading faster without understanding creates more rereading and slower answers.'],
['tables','dilr','Tables & data interpretation','Organize numbers before you calculate.', 'Read units, headings, time periods and footnotes. Translate the question into the exact rows and columns required. Approximate only when answer choices are sufficiently far apart.','Percentage share = part/total × 100. Growth uses the earlier value as the denominator.','Sales move from 80 to 100: growth is 25%, not 20%. A share of 100 out of 400 is 25%.','Percentage points measure the difference between percentages; percent change measures their relative change.'],
['arrangements','dilr','Linear & circular arrangements','Turn conditions into a useful diagram.', 'Write fixed positions first and branch on the most restrictive clue. For circular arrangements, anchor one person to remove rotational duplicates. Check left/right from the seated person’s perspective.','Represent positions explicitly. Keep uncertain possibilities in separate cases rather than forcing a single guess.','Four people sit in a row. A is first, B is immediately left of C, and D is last. The only arrangement is A–B–C–D.','“To the left” does not mean “immediately to the left” unless the clue says so.'],
['sets','dilr','Venn diagrams & grouping','Account for every region exactly once.', 'Use disjoint regions in Venn diagrams. Start with the deepest intersection when three groups are involved, then work outward. Check totals and nonnegative counts.','For two sets: neither = total − |A| − |B| + |A∩B|. Exactly one = |A| + |B| − 2|A∩B|.','Among 60 students, 35 like tea, 30 coffee and 15 both. Union is 50, neither is 10, exactly one is 35.','“A and B” often includes those also in C; “only A and B” excludes C.'],
['games','dilr','Games, tournaments & rankings','Use the structure of the competition.', 'List participants, rounds, scoring and tie rules. Use total matches and points as consistency checks. Distinguish knockout events from round-robin events.','Single round robin with n teams: n(n−1)/2 matches. A knockout without byes needs n−1 matches to find a winner.','Six teams play each other once: 15 matches. With 3 points per win and no draws, total awarded points are 45.','Do not assume a tie-break rule. Use only rules given in the set.'],
['routes','dilr','Routes, networks & scheduling','Map dependencies and bottlenecks.', 'Represent places as nodes and connections as edges. For schedules, write a grid of slots and resources. Apply capacity and precedence constraints before trial and error.','Separate necessary constraints from optional choices. Check every candidate solution against every condition.','If tasks A and B must precede C, and A takes 2 hours while B takes 3 in parallel, C cannot begin before hour 3.','Shortest distance and shortest time can follow different routes.'],
['selection','dilr','Set selection & casework','Choose the right battles.', 'Scan all sets for familiarity, data volume and restrictive conditions. Start with a set whose structure you can represent confidently. Abandon an unproductive case before it consumes the section.','Scan → represent → deduce → answer → verify. Track time per completed set rather than time per isolated clue.','After a few minutes, if your diagram has no firm deductions, reconsider the representation or switch sets.','A short-looking set is not always easy; a long table can be highly structured.']
].map(([id,subject,title,desc,concept,formula,example,trap])=>({id,subject,title,desc,concept,formula,example,trap}));
const Q=[];function q(subject,topic,text,options,answer,explanation){Q.push({id:Q.length+1,subject,topic,text,options,answer,explanation})}
q('qa','percentages','A price is increased by 20% and then decreased by 20%. What is the net change?',['No change','4% decrease','4% increase','8% decrease'],1,'Start at 100. After the increase: 120. After the decrease: 120 × 0.8 = 96. The net decrease is 4%.');
q('qa','ratio','A and B share ₹640 in the ratio 3:5. What is B’s share?',['₹240','₹320','₹400','₹480'],2,'There are 8 equal parts. B receives 5/8 × 640 = ₹400.');
q('qa','work','A can complete a task in 12 days and B in 18 days. Working together at constant rates, how many days do they need?',['6','7.2','8','9'],1,'Their combined rate is 1/12 + 1/18 = 5/36 jobs/day, so the time is 36/5 = 7.2 days.');
q('qa','speed','A car covers equal distances at 40 km/h and 60 km/h. What is its average speed?',['45 km/h','48 km/h','50 km/h','52 km/h'],1,'For equal distances the harmonic mean applies: 2 × 40 × 60 / (40 + 60) = 48 km/h.');
q('qa','profit','An item costs ₹800 and is marked at ₹1,200. It is sold at a 20% discount on marked price. Find the profit percentage.',['16%','20%','25%','40%'],1,'Selling price = 1200 × 0.8 = 960. Profit = 160. Profit percentage = 160/800 × 100 = 20%.');
q('qa','algebra','If x + 1/x = 3, find x² + 1/x².',['5','6','7','9'],2,'Square both sides: x² + 2 + 1/x² = 9. Subtract 2 to obtain 7.');
q('qa','numbers','How many positive divisors does 72 have?',['8','10','12','14'],2,'72 = 2³ × 3². The divisor count is (3+1)(2+1) = 12.');
q('qa','geometry','A right triangle has perpendicular sides of lengths 6 and 8. What is its area?',['24','30','40','48'],0,'Area = ½ × base × height = ½ × 6 × 8 = 24 square units.');
q('qa','modern','Two fair six-sided dice are rolled. What is the probability that their sum is 9?',['1/6','1/9','1/12','1/18'],1,'The favourable ordered outcomes are (3,6), (4,5), (5,4), (6,3): 4 out of 36, or 1/9.');
q('qa','profit','₹10,000 is invested at 10% annual compound interest for 2 years. What is the interest earned?',['₹2,000','₹2,100','₹2,200','₹1,100'],1,'Amount = 10000 × 1.1² = 12100. Interest = 12100 − 10000 = ₹2100.');
q('qa','algebra','What is the smaller root of x² − 7x + 12 = 0?',['2','3','4','6'],1,'Factor as (x−3)(x−4)=0. The roots are 3 and 4; the smaller root is 3.');
q('qa','modern','In how many ways can a committee of 3 be selected from 6 people?',['18','20','60','120'],1,'Order does not matter, so use 6C3 = (6×5×4)/(3×2×1) = 20.');
q('varc','rc','Passage: Urban trees lower local temperatures and improve air quality. Yet planting without long-term maintenance often leads to poor survival. Cities should budget for care as carefully as for planting.\n\nWhat is the main idea?',['Planting trees always fails in cities.','Tree care deserves investment alongside planting.','Air quality matters more than temperature.','Cities should stop planting trees.'],1,'The author endorses trees but argues that maintenance funding is essential. The other options add a priority or an extreme claim absent from the passage.');
q('varc','inference','A museum offers free entry on Sundays. Last Sunday, visitor numbers were twice the usual weekday count. Which conclusion is best supported?',['Free entry was the only cause of the increase.','Every Sunday will have twice as many visitors.','Attendance last Sunday exceeded the usual weekday count.','All visitors prefer free entry.'],2,'Only the observed comparison is certain. The facts do not prove a unique cause, a universal preference, or a future pattern.');
q('varc','summary','Choose the best summary: Digital archives make rare documents easier to access. However, search results can detach an item from its historical setting; access alone does not guarantee understanding.',['Digital archives are useless for historical study.','Digital access broadens availability, but historical context remains essential.','Rare documents should remain inaccessible.','Search engines always distort history.'],1,'The paragraph balances improved access with the need for context. The other options are extreme and erase that balance.');
q('varc','parajumbles','Arrange these sentences logically.\nA. This allowed more residents to borrow books.\nB. A neighbourhood library extended its opening hours.\nC. The increase was especially noticeable among evening workers.\nD. Within a month, lending figures rose.',['B–A–D–C','A–B–C–D','B–C–A–D','D–B–A–C'],0,'B introduces the change; A describes its immediate effect; D reports the outcome; C specifies which group showed the increase.');
q('varc','inference','A cafe owner argues: “If we add outdoor seating, our revenue will increase.” Which assumption is required?',['All indoor seats are uncomfortable.','The outdoor seating can attract some additional revenue.','Every customer prefers outdoor seating.','The cafe has no competitors.'],1,'The conclusion requires some extra revenue from the seating. Universal customer preference, no competitors, and discomfort indoors are unnecessary.');
q('varc','rc','Passage: Experts may disagree not because one lacks facts, but because they assign different weights to uncertain evidence. Productive debate makes those weights explicit.\n\nThe tone is best described as:',['Mocking and hostile','Analytical and constructive','Celebratory and nostalgic','Indifferent and evasive'],1,'The author explains a mechanism of disagreement and proposes a way to improve debate: an analytical, constructive tone.');
q('varc','parajumbles','Which sentence is the odd one out?\n1. Wetlands absorb excess rainwater.\n2. Their vegetation slows surface runoff.\n3. Many cities are redesigning their logos.\n4. Protecting wetlands can therefore reduce flood risk.',['1','2','3','4'],2,'Sentences 1, 2 and 4 form an argument about wetlands and flood mitigation. Sentence 3 concerns city branding.');
q('varc','summary','A company found that shorter meetings saved time only when participants received an agenda beforehand. Without an agenda, discussions often spilled into follow-up meetings. Which summary is accurate?',['Short meetings always save time.','Agendas are unnecessary if meetings are brief.','The time-saving benefit of shorter meetings depended on advance agendas.','Follow-up meetings are always unproductive.'],2,'The main claim is conditional: shorter meetings worked when an agenda was provided. The other options remove the condition or introduce unsupported absolutes.');
q('varc','inference','All members of Club A speak French. Some French speakers speak Japanese. Which statement must be true?',['Some Club A members speak Japanese.','No Club A member speaks Japanese.','Every Club A member speaks French.','All Japanese speakers belong to Club A.'],2,'The first premise directly guarantees that every Club A member speaks French. The Japanese-speaking French speakers may or may not belong to Club A.');
q('varc','rc','Passage: A successful experiment can answer a narrow question while opening several broader ones. Scientific progress therefore often increases the number of questions we can meaningfully ask.\n\nWhich claim would the author most likely accept?',['Progress requires eliminating every uncertainty.','New findings can reveal useful new uncertainties.','An experiment is successful only if it answers broad questions.','More questions prove that science has failed.'],1,'The author sees new questions as a productive consequence of a finding, rather than evidence of failure.');
const data='A shop sold the following units:\nJanuary: books 40, pens 60.\nFebruary: books 50, pens 70.\nMarch: books 60, pens 80.\n';
q('dilr','tables',data+'What is the percentage increase in book sales from January to March?',['20%','33⅓%','50%','60%'],2,'Book sales rose from 40 to 60. Growth = (60−40)/40 × 100 = 50%.');
q('dilr','tables',data+'What fraction of all units sold in February were books?',['5/12','5/7','7/12','1/2'],0,'February total = 50+70 = 120. Book share = 50/120 = 5/12.');
q('dilr','tables',data+'How many pens were sold across all three months?',['180','200','210','230'],2,'Total pens = 60+70+80 = 210.');
const arrange='Four people A, B, C and D sit in a row facing north. A is at the left end. D is at the right end. B is immediately to the left of C.\n';
q('dilr','arrangements',arrange+'Who sits second from the left?',['A','B','C','D'],1,'A and D occupy the ends. The remaining positions must be B then C: A–B–C–D.');
q('dilr','arrangements',arrange+'Who sits immediately to the left of D?',['A','B','C','Cannot be determined'],2,'The unique arrangement is A–B–C–D, so C sits immediately left of D.');
q('dilr','sets','Of 60 students, 35 like tea, 30 like coffee and 15 like both. How many like neither?',['5','10','15','20'],1,'At least one = 35+30−15 = 50. Neither = 60−50 = 10.');
q('dilr','sets','Of 60 students, 35 like tea, 30 like coffee and 15 like both. How many like exactly one of the drinks?',['20','30','35','50'],2,'Tea only = 20; coffee only = 15. Exactly one = 35.');
q('dilr','games','Six teams play a single round-robin tournament, each pair meeting once. How many matches are played?',['12','15','18','30'],1,'Each unordered pair plays once: 6C2 = 6×5/2 = 15 matches.');
q('dilr','routes','Tasks A and B start together. A takes 2 hours, B takes 3 hours. C takes 4 hours and can start only after both finish. What is the earliest total completion time?',['5 hours','6 hours','7 hours','9 hours'],2,'A and B run in parallel, so both are complete after 3 hours. C then takes 4 hours. Total = 7 hours.');
q('dilr','games','A single-elimination tournament begins with 16 players, with no byes or third-place match. How many matches determine the winner?',['8','14','15','16'],2,'Every match eliminates exactly one player. To leave 1 of 16 players, 15 eliminations and therefore 15 matches are needed.');
const navs=[['dashboard','◫','Dashboard'],['learn','▤','Learn & explore'],['practice','✎','Practice arena'],['tests','◷','Mock tests'],['planner','▦','Study planner'],['revision','▱','Revision cards'],['progress','↗','My progress']];
$('#nav').innerHTML=navs.map(([id,icon,label])=>`<a href="#${id}" data-nav="${id}"><span class="icon">${icon}</span>${label}${id==='tests'?'<span class="badge">PRACTICE</span>':''}</a>`).join('');
$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');
const dateKey=()=>new Date().toLocaleDateString('en-CA');
function accuracy(){return state.attempts.length?Math.round(state.attempts.filter(a=>a.correct).length/state.attempts.length*100):0}
function streak(){const dates=new Set(state.attempts.map(a=>new Date(a.time).toLocaleDateString('en-CA')));let n=0,d=new Date();if(!dates.has(d.toLocaleDateString('en-CA')))d.setDate(d.getDate()-1);while(dates.has(d.toLocaleDateString('en-CA'))){n++;d.setDate(d.getDate()-1)}return n}
function heading(kicker,title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function subjectCards(){return subjects.map(s=>{const total=lessons.filter(l=>l.subject===s.id).length,done=lessons.filter(l=>l.subject===s.id&&state.completed.includes(l.id)).length;return `<article class="subject ${s.color}"><div class="subject-top"><div class="subject-symbol">${s.icon}</div><span class="pill">${s.short}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="subject-progress"><span>Your learning progress</span><span>${Math.round(done/total*100)}%</span></div><div class="progress"><i style="width:${done/total*100}%"></i></div><div class="subject-bottom"><span>${done} / ${total} lessons completed</span><a href="#learn/${s.id}">Explore topics &nbsp; →</a></div></article>`}).join('')}
function renderDashboard(){const today=dateKey(),tasks=[['read','Read & reflect','20 min · VARC · One passage, one perspective','VARC'],['quant','A little number crunching','25 min · QA · Percentages & ratios','QA'],['logic','Connect the dots','20 min · DILR · One set, one breakthrough','DILR']];app.innerHTML=heading('LET’S MAKE TODAY COUNT','Your next chapter starts here <span style="font-size:23px">🌤️</span>','A little focus, a little consistency. You’re closer than you think.',`<div class="date-pill">▦ &nbsp; ${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</div>`)+`<section class="hero"><div><div class="eyebrow">YOUR DREAM. YOUR PACE. YOUR JOURNEY.</div><h2>Small steps today.<br>Big possibilities tomorrow.</h2><p>Your all-in-one space to learn, practice, and grow.<br>Let’s turn that IIM dream into a plan.</p><a href="#practice" class="primary">Let’s get started <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="plant">🌱</span><div class="book-stack"><div class="book"></div><div class="book"></div><div class="book"></div></div><span class="spark s1">✧</span><span class="spark s2">✦</span><div class="hero-tag">one step closer ♡</div></div></section><div class="stats"><div class="stat"><div class="stat-icon">♨</div><div><b>${streak()} <small>days</small></b><p>Current streak</p></div></div><div class="stat"><div class="stat-icon">✎</div><div><b>${state.attempts.length}</b><p>Questions practiced</p></div></div><div class="stat"><div class="stat-icon">◎</div><div><b>${accuracy()}<small> %</small></b><p>Overall accuracy</p></div></div><div class="stat"><div class="stat-icon">◷</div><div><b>${state.focus}<small> min</small></b><p>Focused learning</p></div></div></div><div class="section-title"><div><h2>A world of learning, made manageable</h2><p>Three sections. One dream. Find your starting point.</p></div><a href="#learn">View syllabus &nbsp; →</a></div><div class="subject-grid">${subjectCards()}</div><div class="lower-grid"><section class="panel"><div class="section-title"><h2>A little plan for today</h2><span class="mini-day">TODAY</span></div>${tasks.map(([id,t,d,tag])=>`<label class="task ${state.tasks[today+id]?'done':''}"><input type="checkbox" data-task="${id}" ${state.tasks[today+id]?'checked':''}><div><b>${t}</b><p>${d}</p></div><span class="pill">${tag}</span></label>`).join('')}</section><section class="panel"><div class="section-title"><div><h2>Showing up is the first win</h2><p>Your practice activity this week</p></div><span class="pill">7 days</span></div><div class="week-chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const n=state.attempts.filter(a=>new Date(a.time).toLocaleDateString('en-CA')===d.toLocaleDateString('en-CA')).length;return `<div class="day-column ${i===6?'today':''}" title="${n} questions"><i style="height:${Math.min(90,n*10+4)}px"></i><small>${d.toLocaleDateString('en',{weekday:'short'}).slice(0,1)}</small></div>`}).join('')}</div><div class="activity-foot"><span>Every question is a step forward.</span><b>${state.attempts.filter(a=>Date.now()-a.time<7*86400000).length} this week ↗</b></div></section></div><div class="bottom-banner"><span>✧</span><div><b>You don’t have to figure it all out today.</b><p>Just show up. Your future self will thank you.</p></div><a href="#planner">Make my plan &nbsp; →</a></div>`;document.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{state.tasks[today+el.dataset.task]=el.checked;save();el.closest('label').classList.toggle('done',el.checked)})}
let learnFilter='all',search='';
function renderLearn(filter){if(filter)learnFilter=filter;app.innerHTML=heading('BUILD YOUR FOUNDATION','A little clarity goes a long way.','Explore 20 original concept guides across the CAT syllabus.')+`<input class="search" id="lessonSearch" placeholder="Search a topic, like percentages or reading…" aria-label="Search lessons" value="${escapeHTML(search)}"><div class="filters">${[['all','All topics'],...subjects.map(s=>[s.id,s.short])].map(([id,label])=>`<button class="filter ${learnFilter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><div id="lessonGrid" class="lesson-grid"></div><div class="notice">These are concise foundation guides and introductory practice, not an exhaustive textbook or a substitute for full-length exam practice. Complete a lesson, then apply it in the practice arena.</div>`;drawLessons();$('#lessonSearch').oninput=e=>{search=e.target.value;drawLessons()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>renderLearn(b.dataset.filter))}
function drawLessons(){const list=lessons.filter(l=>(learnFilter==='all'||l.subject===learnFilter)&&(l.title+' '+l.desc).toLowerCase().includes(search.toLowerCase()));$('#lessonGrid').innerHTML=list.length?list.map(l=>`<article class="lesson-card"><span class="pill">${l.subject.toUpperCase()} · CONCEPT GUIDE</span><h3>${l.title}</h3><p>${l.desc}</p><button class="${state.completed.includes(l.id)?'secondary':'primary'}" data-lesson="${l.id}">${state.completed.includes(l.id)?'✓ Revisit lesson':'Open lesson →'}</button></article>`).join(''):'<div class="empty">No topics found. Try another search.</div>';document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson))}
function openLesson(id){const l=lessons.find(x=>x.id===id);$('#modalContent').innerHTML=`<article class="article"><span class="pill">${l.subject.toUpperCase()} · FOUNDATION</span><h2>${l.title}</h2><p>${l.concept}</p><h3>Your toolkit</h3><div class="formula">${l.formula}</div><h3>Let’s work through it</h3><p>${l.example}</p><h3>A trap to watch for</h3><p>${l.trap}</p><div class="quiz-actions"><button class="primary" id="completeLesson">${state.completed.includes(id)?'✓ Completed':'Mark as learned'}</button><button class="secondary" id="practiceLesson">Practice this topic →</button></div></article>`;$('#modal').showModal();$('#completeLesson').onclick=()=>{if(!state.completed.includes(id)){state.completed.push(id);save()}$('#completeLesson').textContent='✓ Completed';toast('One concept clearer. Nicely done.');};$('#practiceLesson').onclick=()=>{$('#modal').close();startPractice(l.subject,l.id)}}
$('#modal .close').onclick=()=>{$('#modal').close();if(location.hash.startsWith('#learn'))drawLessons()};$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
let quiz=null,quizTimer=null;
function renderPractice(){app.innerHTML=heading('LEARNING BY DOING','Meet your practice arena.','Original questions. Clear explanations. Room to make mistakes.')+`<div class="subject-grid">${subjects.map(s=>`<article class="subject ${s.color}"><div class="subject-symbol">${s.icon}</div><h3>${s.name}</h3><p>${Q.filter(q=>q.subject===s.id).length} foundation questions · Untimed</p><div class="quiz-actions"><button class="primary" data-practice="${s.id}">Start practicing →</button></div></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="section-title"><h2>Find your focus</h2><span class="pill">${Q.length} original questions</span></div><div class="form-row"><div class="field"><label for="topicSelect">Pick a topic</label><select id="topicSelect">${lessons.filter(l=>Q.some(q=>q.topic===l.id)).map(l=>`<option value="${l.id}">${l.subject.toUpperCase()} · ${l.title}</option>`).join('')}</select></div><button class="primary" id="topicPractice">Practice this topic →</button><button class="secondary" id="mixedPractice">Mixed practice ↗</button></div></section><div class="notice">Practice questions are introductory and have not been calibrated to CAT difficulty or percentile. DILR questions include shared small data sets; full CAT sets are generally more demanding.</div>`;document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>startPractice(b.dataset.practice));$('#mixedPractice').onclick=()=>startPractice();$('#topicPractice').onclick=()=>startPractice(null,$('#topicSelect').value)}
function startPractice(subject,topic){quiz={mode:'practice',questions:Q.filter(q=>(!subject||q.subject===subject)&&(!topic||q.topic===topic)),index:0,answers:{},checked:{},started:Date.now()};renderQuiz()}
function recordAttempt(question,answer){state.attempts.push({id:question.id,subject:question.subject,correct:answer===question.answer,answer,time:Date.now()});save()}
function renderQuiz(){if(!quiz)return;const q=quiz.questions[quiz.index],answer=quiz.answers[q.id],checked=quiz.checked[q.id];app.innerHTML=heading(quiz.mode==='practice'?'MAKE EVERY ATTEMPT COUNT':'TIMED PRACTICE',quiz.mode==='practice'?'Progress over perfection.':quiz.title,quiz.mode==='practice'?'Take your time. Understand the why behind every answer.':'Answer what you can. You can revisit questions before submitting.')+`<div class="quiz-layout"><section class="question-card"><div class="section-title"><span class="pill">${q.subject.toUpperCase()} · QUESTION ${quiz.index+1} OF ${quiz.questions.length}</span>${quiz.mode==='practice'?'<button class="text-button" id="exitPractice">End practice ×</button>':''}</div><h2>${escapeHTML(q.text)}</h2>${q.options.map((o,i)=>`<label class="option ${checked?(i===q.answer?'correct':i===answer?'wrong':''):''}"><input type="radio" name="answer" value="${i}" ${answer===i?'checked':''} ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}.</span><span>${escapeHTML(o)}</span></label>`).join('')}${checked?`<div class="explanation"><b>${answer===q.answer?'✓ That’s right.':'Let’s unpack this.'}</b><br>${q.explanation}</div>`:''}<div class="quiz-actions">${quiz.mode==='practice'&&!checked?'<button class="primary" id="checkAnswer">Check answer →</button>':''}<button class="secondary" id="prevQ" ${quiz.index===0?'disabled':''}>← Previous</button><button class="${checked?'primary':'secondary'}" id="nextQ">${quiz.index===quiz.questions.length-1?'Finish session':'Next question →'}</button>${quiz.mode==='test'?'<button class="secondary" id="clearAnswer">Clear answer</button>':''}</div></section><aside><div class="panel">${quiz.mode==='test'?'<span class="eyebrow">TIME REMAINING</span><div class="timer" id="testTimer"></div>':'<h3 style="font-size:14px">Your practice map</h3>'}<div class="question-map">${quiz.questions.map((x,i)=>`<button class="${i===quiz.index?'current':''} ${quiz.answers[x.id]!==undefined?'answered':''}" data-jump="${i}" aria-label="Go to question ${i+1}">${i+1}</button>`).join('')}</div><p class="muted">Green: answered · Outline: current<br>${quiz.mode==='practice'?'You can skip and revisit any question.':'Scoring: +3 correct, −1 incorrect, 0 unanswered.'}</p>${quiz.mode==='test'?'<button class="primary" id="submitTest">Submit test</button>':''}</div></aside></div>`;document.querySelectorAll('input[name=answer]').forEach(e=>e.onchange=()=>{quiz.answers[q.id]=Number(e.value);document.querySelector(`[data-jump="${quiz.index}"]`).classList.add('answered')});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{quiz.index=Number(b.dataset.jump);renderQuiz()});$('#prevQ').onclick=()=>{if(quiz.index>0){quiz.index--;renderQuiz()}};$('#nextQ').onclick=()=>{if(quiz.index<quiz.questions.length-1){quiz.index++;renderQuiz()}else if(quiz.mode==='test')confirmTest();else finishPractice()};if($('#checkAnswer'))$('#checkAnswer').onclick=()=>{if(quiz.answers[q.id]===undefined){toast('Choose an answer first.');return}quiz.checked[q.id]=true;recordAttempt(q,quiz.answers[q.id]);renderQuiz()};if($('#exitPractice'))$('#exitPractice').onclick=finishPractice;if($('#clearAnswer'))$('#clearAnswer').onclick=()=>{delete quiz.answers[q.id];renderQuiz()};if($('#submitTest'))$('#submitTest').onclick=confirmTest;updateTestTimer()}
function finishPractice(){const count=Object.keys(quiz.checked).length,correct=quiz.questions.filter(q=>quiz.checked[q.id]&&quiz.answers[q.id]===q.answer).length;quiz=null;app.innerHTML=heading('EVERY ATTEMPT COUNTS','A good step forward.','Take the lesson with you, and come back when you’re ready.')+`<section class="panel result"><div class="score">${correct}<span style="font-size:25px"> / ${count}</span></div><p>Checked questions answered correctly.<br>Only checked answers were recorded in your progress.</p><button class="primary" id="morePractice">Keep practicing →</button> <a class="secondary" href="#progress">See my progress</a></section>`;$('#morePractice').onclick=renderPractice}
function renderTests(){app.innerHTML=heading('A LITTLE PRESSURE. A LOT OF LEARNING.','Build your test-day rhythm.','Short, timed practice to help you develop accuracy and selection.')+`<div class="test-grid">${subjects.map(s=>`<article class="test-card"><span class="subject-symbol">${s.icon}</span><h3>${s.short} sprint</h3><p>${Q.filter(q=>q.subject===s.id).length} MCQs · 15 minutes<br>+3 correct · −1 incorrect<br>Review every solution after submission.</p><button class="primary" data-test="${s.id}">Start sprint →</button></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="section-title"><div><h2>Mixed foundation mock</h2><p>Bring all three sections together.</p></div><span class="pill">${Q.length} QUESTIONS</span></div><p class="muted">45 minutes · All MCQs · Free navigation across sections · Automatic submission at the end of the timer.</p><button class="primary" data-test="all">Take the mixed mock →</button></section><div class="notice">These are foundation practice tests, not full-length CAT simulations. They reuse the practice bank, do not enforce CAT section locks, and cannot predict a percentile. For the actual exam, verify the current format at the official CAT website.</div>`;document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>{const subject=b.dataset.test,minutes=subject==='all'?45:15;quiz={mode:'test',title:subject==='all'?'Mixed foundation mock':subject.toUpperCase()+' sprint',questions:subject==='all'?Q:Q.filter(q=>q.subject===subject),index:0,answers:{},checked:{},started:Date.now(),ends:Date.now()+minutes*60000};clearInterval(quizTimer);quizTimer=setInterval(updateTestTimer,1000);renderQuiz()})}
function updateTestTimer(){if(!quiz||quiz.mode!=='test')return;const seconds=Math.max(0,Math.ceil((quiz.ends-Date.now())/1000));if($('#testTimer'))$('#testTimer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0)finishTest()}
function confirmTest(){const unanswered=quiz.questions.filter(q=>quiz.answers[q.id]===undefined).length;$('#modalContent').innerHTML=`<div class="article"><h2>Ready to wrap up?</h2><p>${unanswered} question${unanswered===1?' is':'s are'} unanswered. Unanswered questions receive zero marks. Submitted tests cannot be resumed.</p><button class="primary" id="confirmSubmit">Submit & see results →</button></div>`;$('#modal').showModal();$('#confirmSubmit').onclick=()=>{$('#modal').close();finishTest()}}
function finishTest(){clearInterval(quizTimer);if(!quiz)return;const run=quiz;quiz=null;let correct=0,wrong=0;run.questions.forEach(q=>{if(run.answers[q.id]!==undefined){recordAttempt(q,run.answers[q.id]);if(run.answers[q.id]===q.answer)correct++;else wrong++}});const result={title:run.title,time:Date.now(),correct,wrong,total:run.questions.length,score:correct*3-wrong};state.results.push(result);save();app.innerHTML=heading('INFORMATION, NOT A JUDGEMENT','Your next step starts with this.','Review your reasoning. That’s where the real improvement happens.')+`<section class="panel result"><span class="eyebrow">${run.title}</span><div class="score">${result.score}<span style="font-size:22px"> / ${result.total*3}</span></div><p>${correct} correct · ${wrong} incorrect · ${result.total-correct-wrong} unanswered<br>No percentile is estimated from this practice bank.</p><button class="primary" id="anotherTest">Back to tests →</button></section><h3 style="margin-top:28px;font-size:16px">Your answer review</h3>${run.questions.map((q,i)=>`<section class="panel article" style="margin:14px 0"><span class="pill">${i+1} · ${q.subject.toUpperCase()} · ${run.answers[q.id]===undefined?'UNANSWERED':run.answers[q.id]===q.answer?'CORRECT':'INCORRECT'}</span><p style="white-space:pre-line">${escapeHTML(q.text)}</p><p>Your answer: <b>${run.answers[q.id]===undefined?'—':escapeHTML(q.options[run.answers[q.id]])}</b><br>Correct answer: <b>${escapeHTML(q.options[q.answer])}</b></p><div class="explanation">${q.explanation}</div></section>`).join('')}`;$('#anotherTest').onclick=renderTests;window.scrollTo(0,0)}
function renderPlanner(){const p=state.plan;app.innerHTML=heading('A DREAM WITH A DIRECTION','Make room for your ambition.','A flexible plan that fits around your life. Start where you are.')+`<section class="panel"><div class="form-row"><div class="field"><label for="targetDate">Your target date</label><input type="date" id="targetDate" min="${dateKey()}" value="${p?.target||''}"></div><div class="field"><label for="dailyMinutes">Daily study time</label><select id="dailyMinutes">${[60,90,120,180,240].map(n=>`<option value="${n}" ${p?.minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><button class="primary" id="makePlan">${p?'Update my plan':'Build my plan'} →</button></div><p class="muted">Choose your own planning deadline. This is not an official CAT exam date.</p></section><div id="planOutput"></div>`;if(p)drawPlan();$('#makePlan').onclick=()=>{const target=$('#targetDate').value,minutes=Number($('#dailyMinutes').value);if(!target||new Date(target+'T23:59:59')<new Date()){toast('Choose a target date today or later.');return}state.plan={target,minutes,created:Date.now()};save();drawPlan();toast('Your plan is ready. One day at a time.')};}
function drawPlan(){const p=state.plan,days=Math.max(1,Math.ceil((new Date(p.target+'T23:59:59')-Date.now())/86400000)),weeks=Math.ceil(days/7),qa=Math.round(p.minutes*.4),varc=Math.round(p.minutes*.3),dilr=p.minutes-qa-varc;$('#planOutput').innerHTML=`<div class="stats"><div class="stat"><div><b>${days}</b><p>Days to your target</p></div></div><div class="stat"><div><b>${qa}<small> min</small></b><p>Daily QA</p></div></div><div class="stat"><div><b>${varc}<small> min</small></b><p>Daily VARC</p></div></div><div class="stat"><div><b>${dilr}<small> min</small></b><p>Daily DILR</p></div></div></div><section class="panel"><div class="section-title"><h2>Your ${weeks}-week roadmap</h2><button class="text-button" id="exportPlan">Download plan ↓</button></div>${Array.from({length:Math.min(weeks,52)},(_,i)=>{const phase=i/Math.max(1,weeks-1),name=phase<.4?'Build the foundations':phase<.75?'Apply, connect & practice':'Test, review & refine',l=lessons[i%lessons.length];return `<div class="plan-week"><span class="week-number">${String(i+1).padStart(2,'0')}</span><div><h3>${name}</h3><p>${l.title} + daily reading + one DILR set. ${phase>.7?'Add timed practice and review every error.':'Reserve one session for revision.'}</p></div><span class="pill">${p.minutes*7} min / week</span></div>`}).join('')}${weeks>52?'<p class="muted">First 52 weeks shown. Revisit your plan as your target approaches.</p>':''}</section><div class="notice">The allocation is a starting point, not a prescription. Shift time toward your weakest section using your progress data. As you outgrow the foundation bank, add advanced sets and official-format mocks.</div>`;$('#exportPlan').onclick=()=>download('catalyst-study-plan.txt',`CATalyst study plan\nTarget: ${p.target}\nDaily: QA ${qa} minutes, VARC ${varc} minutes, DILR ${dilr} minutes\n\n`+$('#planOutput .panel').innerText)}
let cardIndex=0,cardBack=false;
function renderRevision(){const l=lessons[cardIndex];app.innerHTML=heading('KEEP THE GOOD STUFF CLOSE','A small refresh. A stronger foundation.','Twenty revision cards for formulas, strategies, and common traps.')+`<div class="flashcard"><span class="pill">${l.subject.toUpperCase()} · CARD ${cardIndex+1} OF ${lessons.length}</span><h2>${l.title}</h2><p>${cardBack?l.formula+'<br><br><b>Watch for:</b> '+l.trap:'Pause for a moment. What are the key ideas you remember?'}</p><button class="primary" id="flipCard">${cardBack?'Show prompt':'Reveal key ideas'} ↻</button></div><div class="flash-actions"><button class="secondary" id="prevCard">← Previous</button><button class="secondary" id="nextCard">Next card →</button></div>`;$('#flipCard').onclick=()=>{cardBack=!cardBack;renderRevision()};$('#prevCard').onclick=()=>{cardIndex=(cardIndex+lessons.length-1)%lessons.length;cardBack=false;renderRevision()};$('#nextCard').onclick=()=>{cardIndex=(cardIndex+1)%lessons.length;cardBack=false;renderRevision()}}
function renderProgress(){app.innerHTML=heading('LOOK HOW FAR YOU’VE COME','Your effort, made visible.','Real practice data. No invented scores, no comparison needed.',`<button class="secondary" id="exportProgress">Export data ↓</button>`)+`<div class="stats"><div class="stat"><div><b>${state.attempts.length}</b><p>Recorded attempts</p></div></div><div class="stat"><div><b>${accuracy()}<small> %</small></b><p>Accuracy</p></div></div><div class="stat"><div><b>${state.completed.length}<small> / 20</small></b><p>Lessons learned</p></div></div><div class="stat"><div><b>${state.results.length}</b><p>Tests completed</p></div></div></div><section class="panel"><div class="section-title"><h2>Find your next focus</h2></div><div class="table-wrap"><table><thead><tr><th>Section</th><th>Attempts</th><th>Correct</th><th>Accuracy</th></tr></thead><tbody>${subjects.map(s=>{const a=state.attempts.filter(x=>x.subject===s.id),n=a.filter(x=>x.correct).length;return `<tr><td>${s.name}</td><td>${a.length}</td><td>${n}</td><td>${a.length?Math.round(n/a.length*100)+'%':'Not started'}</td></tr>`}).join('')}</tbody></table></div><p class="muted">Repeated attempts count toward accuracy. These figures describe your activity here, not an estimated CAT percentile.</p></section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Your error notebook</h2></div>${state.attempts.some(a=>!a.correct)?[...new Set(state.attempts.filter(a=>!a.correct).map(a=>a.id))].map(id=>{const q=Q.find(q=>q.id===id);return `<div class="task"><div><b>${q.subject.toUpperCase()} · ${lessons.find(l=>l.id===q.topic)?.title||q.topic}</b><p>${escapeHTML(q.text.slice(0,100))}…</p></div><button class="text-button" data-retry="${id}">Revisit →</button></div>`}).join(''):'<div class="empty"><h2>A fresh page.</h2><p>Questions you miss will appear here, with a chance to try again.</p><a href="#practice" class="primary">Try a few questions →</a></div>'}</section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Your test history</h2></div>${state.results.length?`<div class="table-wrap"><table><thead><tr><th>Test</th><th>Date</th><th>Score</th><th>Correct / attempted</th></tr></thead><tbody>${[...state.results].reverse().map(r=>`<tr><td>${r.title}</td><td>${new Date(r.time).toLocaleDateString('en-IN')}</td><td>${r.score} / ${r.total*3}</td><td>${r.correct} / ${r.correct+r.wrong}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Your completed timed tests will appear here.</p>'}</section><div class="notice">Your progress is stored in this browser, without an account or cloud sync. Export it before changing browsers or clearing site data. <button class="text-button danger" id="resetProgress">Reset my progress</button></div>`;$('#exportProgress').onclick=()=>download('catalyst-progress.json',JSON.stringify(state,null,2));document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{quiz={mode:'practice',questions:[Q.find(q=>q.id===Number(b.dataset.retry))],index:0,answers:{},checked:{}};renderQuiz()});$('#resetProgress').onclick=()=>{$('#modalContent').innerHTML='<div class="article"><h2>Start a fresh page?</h2><p>This removes all saved attempts, lessons, plans, focus time and test results from this browser. Export your data first if you want to keep it.</p><button class="primary" id="confirmReset">Delete my local progress</button></div>';$('#modal').showModal();$('#confirmReset').onclick=()=>{state={attempts:[],completed:[],tasks:{},results:[],plan:null,focus:0};save();$('#modal').close();renderProgress();toast('Your progress has been reset.')}}}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:name.endsWith('.json')?'application/json':'text/plain'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderGuide(){app.innerHTML=heading('A CLEARER PICTURE','The journey beyond the questions.','Exam essentials, application preparation, and trusted starting points.')+`<div class="resource-grid"><section class="panel article"><span class="pill">EXAM BASICS</span><h3>Know the three sections</h3><p>CAT assesses Verbal Ability & Reading Comprehension, Data Interpretation & Logical Reasoning, and Quantitative Aptitude.</p><p>Recent exams have used a two-hour, section-timed format, with MCQs and non-MCQ questions. Current-year rules, question counts, accessibility provisions and dates must be checked in the official notification.</p><p>Recent scoring has generally awarded +3 for correct answers and −1 for incorrect MCQs, with no negative marking for non-MCQs. Verify the current rules.</p><a href="https://iimcat.ac.in/" target="_blank" rel="noopener">Official CAT website ↗</a></section><section class="panel article"><span class="pill">THE APPLICATION CHECKLIST</span><h3>Keep the essentials together</h3><ul><li>Confirm eligibility from the current official bulletin.</li><li>Keep identity documents, academic records, photograph and signature ready in the required formats.</li><li>Check category and accessibility documentation where applicable.</li><li>Track registration, correction-window, admit-card and exam dates.</li><li>Read each institute’s admission criteria and separate application requirements.</li></ul></section><section class="panel article"><span class="pill">A PRACTICAL PREP LOOP</span><h3>Learn → apply → review → repeat</h3><ul><li>Begin with a diagnostic and identify missing foundations.</li><li>Read daily and map arguments, not just vocabulary.</li><li>Solve QA with a method you can explain.</li><li>Complete DILR sets and review how you represented the information.</li><li>After a mock, classify errors: concept, reading, calculation or selection.</li><li>Protect recovery time and return to weak concepts.</li></ul></section><section class="panel article"><span class="pill">BEYOND THE SCORE</span><h3>Your MBA shortlist & interview prep</h3><p>Compare programmes by fees, placement report methodology, curriculum, location, financial support and your career goals. Verify details on each institute’s official site.</p><p>Prepare a clear account of your academics, work, interests and reasons for pursuing an MBA. Practice discussing current issues using evidence and balanced reasoning.</p><p>Admission decisions may consider sectional scores, academics, experience, category and interviews. A CAT score alone does not guarantee admission.</p></section><section class="panel article"><span class="pill">OPTIONAL EXTERNAL REFERENCES</span><h3>Go deeper when you’re ready</h3><p>For additional advanced practice, structured courses or full-length mocks, explore providers directly:</p><p><a href="https://www.imsindia.com/" target="_blank" rel="noopener">IMS ↗</a> &nbsp; <a href="https://www.time4education.com/" target="_blank" rel="noopener">T.I.M.E. ↗</a> &nbsp; <a href="https://www.careerlauncher.com/cat/" target="_blank" rel="noopener">Career Launcher ↗</a></p><p class="muted">Independent links, with no affiliation. Verify each provider’s current offerings directly. Lessons and questions here are original.</p></section><section class="panel article"><span class="pill">YOUR SPACE, YOUR DATA</span><h3>Simple, private, and local</h3><p>No login is required. Attempts, lesson completion, your plan and focus minutes are kept in your browser’s local storage.</p><p>There is no account sync or server-side backup. You can export progress from My progress. Clearing browser data removes saved work.</p><p>Core learning and practice work without external APIs. Optional external links need an internet connection.</p></section></div>`}
let focusEnd=null,focusInterval;
$('#focusButton').onclick=()=>{if(focusEnd){if(confirm('End this focus session? Completed minutes will be recorded.')){const elapsed=Math.min(25,Math.floor((1500000-(focusEnd-Date.now()))/60000));state.focus+=Math.max(0,elapsed);save();focusEnd=null;clearInterval(focusInterval);$('#focusLabel').textContent='Focus mode'}return}focusEnd=Date.now()+1500000;toast('25 minutes, one thing at a time. You’ve got this.');focusInterval=setInterval(()=>{const s=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));$('#focusLabel').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(!s){state.focus+=25;save();focusEnd=null;clearInterval(focusInterval);$('#focusLabel').textContent='Focus mode';toast('A focused 25 minutes. Take a well-earned break.')}},1000)};
function route(){const [page='dashboard',filter]=location.hash.slice(1).split('/');if(quiz?.mode==='test'){const seconds=Math.max(0,Math.ceil((quiz.ends-Date.now())/1000));if(seconds){toast('Your test is still running. Submit it before leaving.');renderQuiz();return}}quiz=null;clearInterval(quizTimer);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('.sidebar').classList.remove('open');$('#breadcrumb').innerHTML=`Your workspace <span>/</span> ${({dashboard:'Overview',learn:'Learning library',practice:'Practice arena',tests:'Mock tests',planner:'Study planner',revision:'Revision cards',progress:'My progress',guide:'Exam guide'})[page]||'Overview'}`;({dashboard:renderDashboard,learn:()=>renderLearn(filter),practice:renderPractice,tests:renderTests,planner:renderPlanner,revision:renderRevision,progress:renderProgress,guide:renderGuide}[page]||renderDashboard)();window.scrollTo(0,0)}
const foundationRoute=route;window.addEventListener('hashchange',route);window.addEventListener('beforeunload',e=>{if(quiz?.mode==='test'){e.preventDefault();e.returnValue=''}});route();if(!storageOK)toast('Browser storage is unavailable; progress is session-only.');
